window.SHIORI_DATA=window.SHIORI_DATA||{};SHIORI_DATA['n2_p5']={"lk":{"mondai":[{"sec":"moji","no":1,"type":"kanji_reading","instr":"＿＿の言葉の読み方として最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"この地域では、[[伝統]]的な祭りが今も大切に守られている。","options":["でんとう","でんどう","てんとう","てんどう"],"answer":0,"explain":"伝統 is read でんとう (tradition)."},{"q":"方言の使い方には、その土地の歴史が[[反映]]されている。","options":["はんよう","へんえい","はんえい","はんえ"],"answer":2,"explain":"反映 is read はんえい (reflection)."},{"q":"旅館の窓から見える海は、とても[[穏やか]]だった。","options":["なごやか","すこやか","ゆるやか","おだやか"],"answer":3,"explain":"穏やか is read おだやか (calm). 和やか=なごやか, 健やか=すこやか, 緩やか=ゆるやか."},{"q":"雑誌の記事で紹介されると、その店には客が[[殺到]]した。","options":["さつとう","さっとう","ざっとう","せっとう"],"answer":1,"explain":"殺到 is read さっとう (to rush in, flood)."},{"q":"町の図書館では、地域の古い写真を[[収集]]している。","options":["しゅしゅう","しゅうしゅ","しゅうしゅう","しゅうじゅう"],"answer":2,"explain":"収集 is read しゅうしゅう (collecting)."}]},{"sec":"moji","no":2,"type":"orthography","instr":"＿＿の言葉を漢字で書くとき、最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"この番組は、地方の人々の暮らしを[[しょうかい]]している。","options":["招介","紹介","照介","紹会"],"answer":1,"explain":"しょうかい = 紹介 (introduction)."},{"q":"祭りの準備には、多くの住民が[[きょうりょく]]した。","options":["共力","強力","胸力","協力"],"answer":3,"explain":"きょうりょく (cooperate) = 協力. 強力 (powerful) is read きょうりょく too but means 'strong'."},{"q":"台風が近づいているので、旅行の日程を[[へんこう]]することになった。","options":["変更","返更","変行","偏更"],"answer":0,"explain":"へんこう = 変更 (change)."},{"q":"駅前の{商店街|しょうてんがい}は、週末になると買い物客で[[こんざつ]]する。","options":["困雑","混難","混雑","婚雑"],"answer":2,"explain":"こんざつ = 混雑 (crowded)."},{"q":"旅館に着いたので、まずフロントで荷物を[[あずけた]]。","options":["預けた","頼けた","領けた","項けた"],"answer":0,"explain":"あずける = 預ける (leave in someone's care)."}]},{"sec":"moji","no":3,"type":"word_formation","instr":"（　　）に入れるのに最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"三十年前に話題になったその映画が、来月から映画館で（　　）上映される。","options":["改","再","復","重"],"answer":1,"explain":"再上映 = showing again (re-screening)."},{"q":"最近は、若者の新聞（　　）が進んでいると言われている。","options":["外れ","抜け","{離|ばな}れ","去り"],"answer":2,"explain":"〜離れ = drifting away from something: 新聞離れ (people no longer reading newspapers)."},{"q":"その旅番組は放送が始まってすぐに、高い{視聴|しちょう}（　　）を記録した。","options":["度","量","割","率"],"answer":3,"explain":"視聴率 = TV audience rating."},{"q":"会議での彼の発言は、（　　）常識だと多くの人から批判された。","options":["非","不","無","未"],"answer":0,"explain":"非常識 = lacking common sense."},{"q":"今回泊まった宿は、二食（　　）で一泊一万二千円だった。","options":["入り","持ち","付き","連れ"],"answer":2,"explain":"二食付き = with two meals included."}]},{"sec":"moji","no":4,"type":"context","instr":"（　　）に入れるのに最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"祖母は子どものころの話をするとき、{懐|なつ}かしそうに目を（　　）。","options":["狭める","細める","{縮|ちぢ}める","弱める"],"answer":1,"explain":"目を細める = to narrow one's eyes (with fondness/joy)."},{"q":"日本語には、はっきり言わずに、相手に気持ちを（　　）ような表現が多い。","options":["察してもらう","見逃してもらう","打ち明けてもらう","取り次いでもらう"],"answer":0,"explain":"察してもらう = have the other person sense/infer (your feelings) without being told."},{"q":"人気の温泉地は、連休になると宿の予約が（　　）取れない。","options":["ようやく","せめて","なかなか","いきなり"],"answer":2,"explain":"なかなか〜ない = not easily. Reservations are hard to get."},{"q":"この地域の方言は、文の終わりが上がる独特の（　　）がある。","options":["リハーサル","ナレーション","インタビュー","イントネーション"],"answer":3,"explain":"イントネーション = intonation, the rise and fall of the voice."},{"q":"展示の説明は英語や中国語にも{翻訳|ほんやく}されていて、外国人の見学者への（　　）が感じられる。","options":["{配慮|はいりょ}","{遠慮|えんりょ}","{考慮|こうりょ}","{思慮|しりょ}"],"answer":0,"explain":"配慮 = consideration/care shown for others. 考慮 is 'taking into account', not used for thoughtfulness toward people this way."},{"q":"彼女は地元のラジオ局で、毎朝天気や交通の情報を（　　）伝えている。","options":["のろのろと","はきはきと","ぶつぶつと","ひそひそと"],"answer":1,"explain":"はきはきと = clearly and crisply, the right way to speak on radio. ぶつぶつ = grumbling, ひそひそ = whispering, のろのろ = sluggishly."},{"q":"五十年続いた{商店街|しょうてんがい}の夏祭りが、手伝う人が足りないため、今年で（　　）ことになった。","options":["取り入れられる","見逃される","打ち切られる","打ち明けられる"],"answer":2,"explain":"打ち切られる = to be discontinued/ended."}]},{"sec":"moji","no":5,"type":"paraphrase","instr":"＿＿の言葉に意味が最も近いものを、１・２・３・４から一つ選びなさい。","items":[{"q":"その旅館で食べた料理の味は[[格別]]だった。","options":["量が多かった","意外に安かった","珍しかった","特によかった"],"answer":3,"explain":"格別 = exceptional, particularly good."},{"q":"観光ガイドの説明は[[くどかった]]。","options":["しつこくて長かった","わかりにくかった","短すぎた","声が小さかった"],"answer":0,"explain":"くどい = long-winded, repetitive."},{"q":"町の人たちは、新しい美術館を建てる計画に[[否定的]]だ。","options":["賛成している","反対している","関心がない","期待している"],"answer":1,"explain":"否定的 = negative, against it."},{"q":"開場すると、会場は[[たちまち]]人でいっぱいになった。","options":["しばらくして","いつの間にか","あっという間に","少しずつ"],"answer":2,"explain":"たちまち = instantly, in no time."},{"q":"祭りに参加するかどうか聞いたが、彼の返事は[[あいまい]]だった。","options":["冷たかった","はっきりしなかった","遅かった","{丁寧|ていねい}だった"],"answer":1,"explain":"あいまい = vague, unclear."}]},{"sec":"moji","no":6,"type":"usage","instr":"次の言葉の使い方として最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"名所","word":"名所","options":["彼は料理の名所で、どんな料理でも上手に作れる。","会議の名所を確認してから、会社を出た。","この寺は{桜|さくら}の名所として知られ、春には多くの人が訪れる。","この小説の一番の名所は、最後の章だ。"],"answer":2,"explain":"名所 = a famous sight/spot. 1 needs 名人, 2 needs 場所, 4 needs 見どころ."},{"q":"味わう","word":"味わう","options":["旅先では、その土地ならではの{雰囲気|ふんいき}をゆっくり味わいたい。","スープの塩は、少し味わってから入れてください。","彼の意見をよく味わってから、質問に答えた。","毎朝駅まで歩いて、体力を味わっている。"],"answer":0,"explain":"味わう = to savor/experience. 2 needs 味見して, 3 needs 聞いて/考えて, 4 needs つけている."},{"q":"手軽","word":"手軽","options":["彼は手軽な性格なので、{誰|だれ}とでもすぐ仲良くなる。","この荷物は手軽だから、一人でも運べるだろう。","心配していた試験が手軽に終わって、ほっとした。","スマートフォンがあれば、海外のニュースも手軽に読めるようになった。"],"answer":3,"explain":"手軽 = easy, without effort or trouble. 1 needs 気さく/気軽, 2 needs 軽い, 3 needs 無事に."},{"q":"{普及|ふきゅう}","word":"{普及|ふきゅう}","options":["台風の被害が、町全体に{普及|ふきゅう}した。","インターネットの{普及|ふきゅう}によって、地方の小さな店も全国に商品を売れるようになった。","手術のあと、父の体力は少しずつ{普及|ふきゅう}している。","その{噂|うわさ}は、あっという間にクラス中に{普及|ふきゅう}した。"],"answer":1,"explain":"普及 = (technology, products, ideas) spreading into wide use. 1 needs 広がった, 3 needs 回復, 4 needs 広まった."},{"q":"ずらりと","word":"ずらりと","options":["彼は約束の時間に、ずらりと遅れてやって来た。","昨日から雨がずらりと降り続いている。","通りの両側には、祭りの屋台がずらりと並んでいた。","先生の話を聞いて、ずらりと安心した。"],"answer":2,"explain":"ずらりと = in a long row, lined up. Used with 並ぶ."}]},{"sec":"bunpo","no":7,"type":"grammar_form","instr":"次の文の（　　）に入れるのに最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"この町の祭りは三百年（　　）続いており、住民の{誇|ほこ}りとなっている。","options":["にかけて","について","にわたって","に対して"],"answer":2,"explain":"〜にわたって = over a whole span (of time). にかけて needs a range like 春から夏にかけて."},{"q":"せっかく日本に来た（　　）、一度は{富士山|ふじさん}に登ってみたい。","options":["からには","ものの","わりに","とたん"],"answer":0,"explain":"〜からには = since (I've done X), I should/want to... Fits the wish that follows."},{"q":"彼は仕事の忙しさの（　　）、友人との約束をすっかり忘れてしまった。","options":["ことに","あまり","かぎり","ばかりに"],"answer":1,"explain":"Nのあまり = because of too much N. ばかりに attaches to verbs/adjectives (忙しいばかりに), not 忙しさの."},{"q":"講演では、現地で{撮|と}った写真（　　）、旅の体験を分かりやすく話してくれた。","options":["をめぐって","を問わず","をこめて","を交えて"],"answer":3,"explain":"〜を交えて = mixing in, including (photos while talking)."},{"q":"方言は最初は聞き取りにくい（　　）、慣れてくると温かみが感じられるようになる。","options":["ものの","ものなら","ことから","ものだから"],"answer":0,"explain":"〜ものの = although. Contrast between 'hard to catch' and 'feel warmth later'."},{"q":"たとえ雨が降ろう（　　）、祭りは予定通り行われる。","options":["ので","ば","と","なら"],"answer":2,"explain":"Volitional form + と = even if. たとえ雨が降ろうと."},{"q":"この店のそばは、一度食べたら忘れ（　　）おいしさだ。","options":["かねない","っぽい","がちな","がたい"],"answer":3,"explain":"〜がたい = hard to (do). 忘れがたい = unforgettable."},{"q":"彼女の旅行記は、読んでいる（　　）、まるで自分もその町を歩いているような気分になる。","options":["ところに","うちに","最中に","あいだを"],"answer":1,"explain":"〜ているうちに = while doing, (a change happens naturally)."},{"q":"国によって習慣が違うのは当然だ。自分の国の常識が、どこでも通用する（　　）。","options":["とは限らない","にすぎない","わけにはいかない","に違いない"],"answer":0,"explain":"〜とは限らない = it's not necessarily the case."},{"q":"この地方の家庭料理は、季節（　　）使う野菜が変わる。","options":["ぶりに","おきに","ごとに","ずつに"],"answer":2,"explain":"〜ごとに = with each (season). 〜おきに means 'every other'."},{"q":"A「この漢字、何て読むか分かる？」\nB「うーん、読めない（　　）けど、あまり自信はないなあ。」","options":["わけがない","はずがない","どころではない","こともない"],"answer":3,"explain":"〜ないこともない = it's not that I can't (I sort of can). Matches 'but I'm not confident'."},{"q":"先日は遠いところ、わざわざ展示会の会場まで（　　）、ありがとうございました。","options":["参ってくださり","お越しくださり","お伺いになり","ご{覧|らん}になり"],"answer":1,"explain":"お越しくださる = honorific 'come'. 参る and 伺う are humble and can't describe the listener's action."}]},{"sec":"bunpo","no":8,"type":"ordering","instr":"次の文の　★　に入る最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"この町の和菓子は、 ＿＿＿ ＿＿＿ ＿★＿ ＿＿＿ 人気がある。","options":["だけでなく","観光客","地元の人","にも"],"order":[2,0,1,3],"answer":1,"explain":"地元の人 だけでなく 観光客 にも 人気がある。★ = 観光客."},{"q":"日本語は勉強すればする ＿＿＿ ＿★＿ ＿＿＿ ＿＿＿ 気がする。","options":["わかってくる","ほど","ような","奥の深さが"],"order":[1,3,0,2],"answer":3,"explain":"勉強すればする ほど 奥の深さが わかってくる ような 気がする。★ = 奥の深さが."},{"q":"昔の人の知恵が ＿＿＿ ＿＿＿ ＿★＿ ＿＿＿ {驚|おどろ}かされる。","options":["にも","生かされていることに","今の","暮らし"],"order":[2,3,0,1],"answer":0,"explain":"今の 暮らし にも 生かされていることに 驚かされる。★ = にも."},{"q":"旅の楽しみは、有名な観光地を ＿＿＿ ＿＿＿ ＿★＿ ＿＿＿ にあると思う。","options":["出会い","よりむしろ","回ること","地元の人との"],"order":[2,1,3,0],"answer":3,"explain":"回ること よりむしろ 地元の人との 出会い にあると思う。★ = 地元の人との."},{"q":"祖父が若いころに ＿＿＿ ＿＿＿ ＿★＿ ＿＿＿ 、今でも多くの客に愛されている。","options":["という","旅館は","この","建てた"],"order":[3,0,2,1],"answer":2,"explain":"建てた という この 旅館は、今でも… ★ = この."}]},{"sec":"bunpo","no":9,"type":"text_grammar","instr":"次の文章を読んで、文章全体の内容を考えて、（５０）から（５４）の中に入る最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"以下は、留学生が書いた作文である。\n\n方言との出会い\n\n　日本に来て最初の一年、私は東京の日本語学校で勉強した。教科書で学ぶ日本語は、テレビのニュースで聞く日本語とほとんど同じだったので、日本語はどこでも同じだと思っていた。（５０）、大学に入学するために地方の町に引っ越して、その考えは大きく変わった。\n　引っ越した日、アパートの大家さんに{挨拶|あいさつ}に行くと、大家さんは笑顔で色々なことを話してくれた。しかし、私には半分も分からなかった。（５１）日本語なのに、まるで外国語を聞いているようだった。\n　それから私は、近所の人や大学の友人が話す言葉をノートに書き留めるようにした。分からない言葉があれば、その意味を（５２）。すると、方言には、標準語では表しにくい細かい気持ちを伝える言葉が多いことに気がついた。\n　今では、私も少しずつ方言を使うようになった。私が方言で話すと、地元の人はとても喜んでくれる。言葉は単に情報を伝えるための道具（５３）、人と人との{距離|きょり}を{縮|ちぢ}めるものでもあるのだ。\n　卒業後は東京で働く予定だが、この町の言葉を（５４）。","questions":[{"q":"50","options":["そのうえ","ところが","つまり","それなら"],"answer":1,"explain":"ところが = however; the writer's belief was then overturned."},{"q":"51","options":["たとえ","せっかく","まさか","確かに"],"answer":3,"explain":"確かに日本語なのに = it was certainly Japanese, and yet..."},{"q":"52","options":["その場で{尋|たず}ねることにした","{尋|たず}ねずにはすまなかった","{尋|たず}ねるわけにはいかなかった","{尋|たず}ねたばかりだった"],"answer":0,"explain":"She made a habit of asking on the spot; that led to the discovery (すると…気がついた)."},{"q":"53","options":["にすぎないので","というより","であるだけでなく","であるからこそ"],"answer":2,"explain":"単に…であるだけでなく、…でもある = not merely X but also Y."},{"q":"54","options":["忘れずにいたいと思う","忘れてしまいかねない","忘れるわけがなかった","忘れたことにしたい"],"answer":0,"explain":"The writer wants to keep the town's dialect in mind even after moving away."}]}]},{"sec":"dokkai","no":10,"type":"short","instr":"次の(1)から(5)の文章を読んで、後の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"（１）\n　映画の{字幕|じまく}には、一秒あたりに表示できる文字数に限りがある。そのため{字幕|じまく}{翻訳者|ほんやくしゃ}は、登場人物のせりふをそのまま{訳|やく}すのではなく、観客が画面を見ながら無理なく読める長さにまとめなければならない。もとのせりふの半分以下になることも珍しくない。しかし、ただ短くすればいいというわけではない。言葉を{削|けず}っても、その人物の性格や場面の{雰囲気|ふんいき}が伝わらなければ、よい{字幕|じまく}とは言えないのである。","questions":[{"q":"筆者によると、よい{字幕|じまく}とはどのようなものか。","options":["もとのせりふをできるだけ正確に{訳|やく}したもの","文字数を減らしながらも、人物や場面の感じが伝わるもの","観客が読みやすいように、せりふを必ず半分以下にしたもの","画面の{邪魔|じゃま}にならないように、短い言葉だけを使ったもの"],"answer":1,"explain":"The last sentence: even with words cut, it must convey the character's personality and the mood of the scene."}]},{"text":"（２）\n以下は、市民文化センターから届いたメールである。\n\n日本の{伝統|でんとう}文化体験講座　参加者の皆様\n\nいつも当センターをご利用いただき、ありがとうございます。\n11月18日（土）に予定しておりました「着物の着付け体験」は、講師の急病のため、11月25日（土）に延期させていただくことになりました。時間と会場に変更はありません。\n25日のご都合が悪い方には参加費を全額お返しいたしますので、11月20日（月）までに受付までお電話ください。なお、ご連絡がない場合は、25日にご参加いただけるものとして準備を進めます。\nご{迷惑|めいわく}をおかけし、申し{訳|わけ}ございません。","questions":[{"q":"25日に参加できない人は、どうしなければならないか。","options":["18日に会場へ行って、参加費を受け取る。","25日までに、受付へ参加費を払いに行く。","特に何もしなくてもいい。","20日までに、センターに電話で連絡する。"],"answer":3,"explain":"Those who can't attend on the 25th should phone reception by the 20th to get a refund; if they don't call, they are counted as attending."}]},{"text":"（３）\n　{新幹線|しんかんせん}や飛行機のおかげで、遠い町にも日帰りで行けるようになった。便利になったのは確かだが、私はときどき、あえて各駅停車の列車を選ぶ。窓の外の景色がゆっくり変わっていくのを{眺|なが}めていると、乗ってくる人の言葉や服装も少しずつ変わっていくのに気づく。そうした変化の中に、地図を見ているだけでは分からない、土地と土地のつながりが感じられるのだ。速さと引き換えに、私たちはこうした楽しみを手放してしまったのかもしれない。","questions":[{"q":"筆者が各駅停車の列車を選ぶのはなぜか。","options":["移動の途中で、土地の変化やつながりを感じられるから","{新幹線|しんかんせん}や飛行機より料金が安いから","遠い町に日帰りで行くことができるから","地図では分からない近道を知ることができるから"],"answer":0,"explain":"On slow trains the writer notices gradual changes in people's speech and clothes and feels the connections between places."}]},{"text":"（４）\n　大きな{災害|さいがい}が起きたとき、地域のコミュニティFMが果たす役割は大きい。全国向けのテレビやラジオは、被害の全体の様子を伝えることはできても、「どこの{避難所|ひなんじょ}で水が配られているか」「どの道路が通れるか」といった細かい情報までは伝えきれない。普段から地域の店や行事を紹介している局だからこそ、住民が本当に必要としている情報をすぐに届けることができるのだ。こうした局の多くは小さな予算で運営されているが、その価値は{規模|きぼ}だけでは測れない。","questions":[{"q":"筆者の考えに合うものはどれか。","options":["{災害|さいがい}のときには、全国向けの放送より地域の放送のほうが正確だ。","コミュニティFMは、予算を増やして{規模|きぼ}を大きくするべきだ。","普段から地域に{密着|みっちゃく}しているので、{災害|さいがい}のときに役立つ情報を伝えられる。","{災害|さいがい}の全体の様子を伝えることが、コミュニティFMの役割だ。"],"answer":2,"explain":"だからこそ: because they cover local shops and events day to day, they can deliver the detailed information residents need."}]},{"text":"（５）\n　役所の広報誌などについて、カタカナ語が多すぎるという意見をよく耳にする。確かに、高齢者にとって分かりにくい言葉が増えるのは問題だ。かといって、カタカナ語を一つ残らず漢字の言葉に置き換えるのがよいとも言えない。無理に言い換えると、かえって意味が伝わりにくくなる場合もあるからだ。大切なのは、読む人が{誰|だれ}なのかを考え、その人にとって分かりやすい言葉を選ぶことである。","questions":[{"q":"筆者の考えに合うものはどれか。","options":["言葉を選ぶときは、読み手のことを考えることが大切だ。","広報誌では、カタカナ語を使うべきではない。","カタカナ語は、漢字の言葉より分かりやすい。","高齢者向けの文章では、漢字の言葉を使うほうがいい。"],"answer":0,"explain":"The conclusion: what matters is thinking about who the reader is and choosing words that are clear to them."}]}]},{"sec":"dokkai","no":11,"type":"mid","instr":"次の(1)から(3)の文章を読んで、後の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"（１）\n　数年前まで、ほとんど知られていなかった山あいの小さな村がある。ある旅行者がSNSに{投稿|とうこう}した一枚の写真がきっかけで、その村の{棚田|たなだ}は一気に有名になった。週末になると、カメラを持った人々が次々に訪れるようになり、村には活気が戻ったように見えた。\n　ところが、間もなく問題が起き始めた。田んぼのあぜ道に勝手に入る人や、農作業をしている住民に断りもなくカメラを向ける人が現れたのだ。村には駐車場もトイレも十分になく、細い道は車でふさがれてしまった。住民の中には、「静かな暮らしを返してほしい」と言う人も出てきた。\n　そこで村は、観光客を{締|し}め出すのではなく、受け入れ方を工夫することにした。{撮影|さつえい}に適した場所を決めて案内板を立て、週末には地元の若者がガイドとして村を案内する。ガイドの話を聞いた観光客の多くは、{棚田|たなだ}が何百年もの間、住民の手で守られてきたことを知り、あぜ道を歩くときにも気をつけるようになったという。\n　観光客が増えることは、地域にとって大きな力になる。しかし、それが住民の暮らしを{壊|こわ}してしまっては意味がない。大切なのは、訪れる人に、その風景がどのように守られてきたのかを知ってもらうことだと私は思う。","questions":[{"q":"「村には活気が戻ったように見えた」とあるが、なぜそう見えたのか。","options":["若者が村に戻ってきて、農業を始めたから","写真をきっかけに、多くの人が村を訪れるようになったから","村がSNSを使って、{棚田|たなだ}を紹介し始めたから","村に新しい駐車場やトイレができたから"],"answer":1,"explain":"After a traveller's photo went viral, people with cameras came every weekend."},{"q":"村が行ったこととして、合うものはどれか。","options":["観光客が村に入れる日を、週末だけに決めた。","写真を{撮|と}る人から、料金を取ることにした。","{撮影|さつえい}する場所を決め、地元の若者が村を案内するようにした。","あぜ道に入ることを禁止する看板を立てた。"],"answer":2,"explain":"The village set photo spots with signboards and had local young people guide visitors at weekends."},{"q":"筆者の考えに合うものはどれか。","options":["観光客に、風景が守られてきた背景を伝えることが大切だ。","観光客の数を減らすことが、住民の暮らしを守る一番の方法だ。","観光客を増やすためには、SNSをもっと利用するべきだ。","住民が観光客に合わせて、暮らし方を変えるべきだ。"],"answer":0,"explain":"Last sentence: what matters is letting visitors learn how the landscape has been protected."}]},{"text":"（２）\n　私は落語家になって二十年になる。落語は{江戸時代|えどじだい}から続く話芸だが、今の客席には、着物で暮らす生活や長屋の様子を見たことがない若い人も多い。昔の言葉をそのまま使うと、笑ってほしいところで客席が静まり返ってしまうこともある。\n　若いころ、私は{師匠|ししょう}に「{古典|こてん}は{一字一句|いちじいっく}変えてはいけないのですか」と聞いたことがある。{師匠|ししょう}は少し考えてから、「変えてはいけないのは話の{芯|しん}だ。言葉は客に合わせて選べばいい」と答えた。当時の私には、その意味がよく分からなかった。{噺|はなし}を変えることは、先人に対して失礼なことのように思えたからだ。\n　しかし、高座に上がる回数が増えるにつれて、{師匠|ししょう}の言葉が少しずつ分かるようになってきた。落語の面白さは、知らない言葉の意味にあるのではなく、人間の弱さやおかしさにある。その部分さえしっかり伝われば、今の客にも昔と同じように笑ってもらえる。逆に、言葉だけを守っても、客に伝わらなければ、{噺|はなし}は生きたものにならない。\n　{古典|こてん}を守るというのは、古いものを箱にしまっておくことではない。その時代の客の前で演じ続けることで、初めて{噺|はなし}は次の世代に受け{継|つ}がれていくのだと、今は思っている。","questions":[{"q":"若いころの筆者は、{噺|はなし}を変えることについてどう考えていたか。","options":["客に合わせるためには、必要なことだ。","昔の落語家たちに対して、失礼なことだ。","若い客を増やすためには、仕方がないことだ。","{師匠|ししょう}の許可があれば、してもいいことだ。"],"answer":1,"explain":"噺を変えることは、先人に対して失礼なことのように思えた — it seemed disrespectful to those who came before."},{"q":"筆者によると、落語の面白さはどこにあるか。","options":["昔の言葉や暮らしを知ることができるところ","{師匠|ししょう}から習った言葉を、そのまま聞けるところ","客席が静まり返るような{緊張感|きんちょうかん}があるところ","人間の弱さやおかしさが{描|えが}かれているところ"],"answer":3,"explain":"落語の面白さは…人間の弱さやおかしさにある."},{"q":"筆者は、{古典|こてん}を守るとはどういうことだと考えているか。","options":["古い{噺|はなし}を正しく記録して、そのまま残しておくこと","話の{芯|しん}を変えずに、今の客の前で演じ続けること","昔の言葉の意味を、客に説明しながら話すこと","新しい{噺|はなし}を作って、{古典|こてん}の代わりにすること"],"answer":1,"explain":"Keeping the core (芯) and performing for the audience of each era is how the stories are handed down."}]},{"text":"（３）\n　知らない町を歩くとき、私たちはスマートフォンの地図アプリに頼ることが多い。目的地を入力すれば最短の道順を示してくれるので、道に迷うことはほとんどなくなった。\n　しかし先日、旅先でスマートフォンの電池が切れてしまい、久しぶりに地図を持たずに町を歩くことになった。最初は不安だったが、駅の案内板を見たり、店の人に道を{尋|たず}ねたりしながら進むうちに、不思議と町の様子がよく見えてきた。路地の奥にある古い神社や、地元の人しか来ないような小さな食堂など、アプリの画面を見ながら歩いていたら、きっと見逃していただろう。道を教えてくれた八百屋の主人は、ついでに近くで開かれる祭りのことまで教えてくれた。\n　アプリは、決められた場所に効率よく行くためには非常に便利な道具だ。だが、旅の楽しみが思いがけないものに出会うことにあるとすれば、効率のよさが必ずしも旅を豊かにしてくれるわけではない。\n　もちろん、アプリを使うなと言いたいのではない。ただ、ときには画面から目を{離|はな}し、少し遠回りをしてみるのも悪くないと思う。","questions":[{"q":"電池が切れたあと、筆者はどのように町を歩いたか。","options":["案内板を見たり、人に聞いたりしながら歩いた。","店で地図を買って、それを見ながら歩いた。","地元の人に、目的地まで連れて行ってもらった。","不安だったので、駅の近くだけを歩いた。"],"answer":0,"explain":"駅の案内板を見たり、店の人に道を尋ねたりしながら進んだ."},{"q":"「きっと見逃していただろう」とあるが、何を見逃していたというのか。","options":["スマートフォンの電池が少なくなっていること","駅にある町の案内板","町の中にある、目立たないが{魅力|みりょく}のある場所","目的地までの最短の道順"],"answer":2,"explain":"The old shrine down an alley and the little diner only locals use — places that are easy to miss."},{"q":"この文章で筆者が最も言いたいことは何か。","options":["旅行のときは、地図アプリを使わないほうがいい。","道に迷ったら、地元の人に聞くのが一番だ。","地図アプリは、旅をより効率的で豊かなものにする。","ときには効率を気にせず、町を歩いてみるのもいい。"],"answer":3,"explain":"The writer doesn't reject apps, but suggests looking up from the screen and taking a detour now and then."}]}]},{"sec":"dokkai","no":12,"type":"compare","instr":"次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"A\n　{翻訳|ほんやく}アプリの性能は年々上がっている。スマートフォンに話しかけるだけで、相手の国の言葉がすぐに表示され、読み上げてもくれる。海外旅行で道を聞いたり、レストランで注文したりする程度なら、困ることはほとんどなくなった。そう考えると、仕事で必要な人を除けば、何年もかけて外国語を学ぶ必要は、以前ほどないのではないか。その時間を別のことに使うほうが合理的だろう。ただし、アプリは間違えることもあるので、{契約|けいやく}のような大事な場面では、専門の{通訳者|つうやくしゃ}に頼るべきである。\n\nB\n　{翻訳|ほんやく}アプリが便利なのは確かだ。私も旅先でよく使っている。しかし、言葉を学ぶことは、単に意思を伝える手段を手に入れることではない。外国語を学ぶ過程で、私たちはその言葉を話す人々の考え方や文化に触れることができる。例えば、ある言葉に敬語がどのくらいあるかを知るだけでも、その社会の人間関係が見えてくる。また、旅先で片言でも現地の言葉で{挨拶|あいさつ}すると、相手の表情がふっと和らぐ。そうした{瞬間|しゅんかん}は、アプリでは生み出せないものだ。","questions":[{"q":"AとBのどちらの文章にも触れられている点は何か。","options":["{翻訳|ほんやく}アプリが間違えること","外国語を学ぶのにかかる時間","{翻訳|ほんやく}アプリの便利さ","外国語を学ぶことで文化に触れられること"],"answer":2,"explain":"A describes how well apps work; B also says 翻訳アプリが便利なのは確かだ. Errors and time appear only in A, culture only in B."},{"q":"外国語を学ぶことについて、AとBはどのように述べているか。","options":["AもBも、旅行のためには外国語を学ぶべきだと述べている。","Aは多くの人にとって以前ほど必要ではないと述べ、Bは文化を知るうえで意味があると述べている。","Aは仕事のために学ぶべきだと述べ、Bはアプリがあれば十分だと述べている。","AもBも、{翻訳|ほんやく}アプリがあれば学ぶ必要はないと述べている。"],"answer":1,"explain":"A: apart from work, there's less need than before. B: learning a language lets you touch the culture and people's way of thinking."}]}]},{"sec":"dokkai","no":13,"type":"opinion","instr":"次の文章を読んで、後の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"　新聞の{投書欄|とうしょらん}には、ときどき「最近の若者の言葉は乱れている」という意見が{載|の}る。「ら抜き言葉」や、何にでも「やばい」を使う言い方などが、よく例として{挙|あ}げられる。こうした意見を読むたびに、私は少し複雑な気持ちになる。\n　言葉が時代とともに変わっていくのは、ごく自然なことである。今では正しいとされている言い方の中にも、かつては「誤り」だと批判されたものが少なくない。例えば、「全然」の後には否定の言葉が来なければならないと考える人は多いが、明治時代の小説には「全然正しい」のような使い方も見られるという。何が正しく何が誤りかは、その時代の多くの人がどう使っているかによって決まる面があるのだ。\n　また、新しい言い方が広がるのには、それなりの理由がある。「ら抜き言葉」は、「見られる」が「見ることができる」という意味なのか、「人に見られる」という意味なのかを区別しやすくする働きを持っていると言われる。若者の言葉を単なる乱れとして切り捨ててしまうと、言葉が持つこうした工夫に気づくことができない。\n　しかし、だからといって、どんな言葉づかいでもかまわないと考えているわけではない。言葉は、相手に伝わってはじめて役に立つものである。仲間{同士|どうし}では自然に通じる表現でも、世代や立場の異なる相手には意味が伝わらなかったり、失礼な印象を与えたりすることがある。問題なのは、新しい言葉そのものではなく、相手や場面を考えずに言葉を使ってしまうことなのである。\n　考えてみれば、私たちは{誰|だれ}でも、いくつかの言葉を使い分けながら暮らしている。家族と話すときと職場で話すときとでは、同じ人でも言葉が違う。方言と共通語を場面によって使い分けている人も多い。若者も同じで、友人の前では流行の言葉を使っていても、面接の場ではきちんとした敬語で話そうと努力している。\n　言葉の変化を{嘆|なげ}くより、さまざまな言葉の中から、その場にふさわしいものを選ぶ力を育てることのほうが大切だと私は思う。そのためには、まず大人自身が、自分と違う言葉づかいに耳を傾け、なぜその言葉が使われているのかを考えてみることから始めるべきではないだろうか。","questions":[{"q":"筆者によると、言葉の正しさはどのように決まる面があるか。","options":["辞書や教科書に書かれているかどうかによって決まる。","その時代の多くの人の使い方によって決まる。","昔から使われてきたかどうかによって決まる。","専門家がどう判断するかによって決まる。"],"answer":1,"explain":"何が正しく何が誤りかは、その時代の多くの人がどう使っているかによって決まる面がある."},{"q":"筆者は、何が問題だと考えているか。","options":["若者が新しい言葉を次々に作り出すこと","若者が敬語を使えなくなっていること","相手や場面を考えずに言葉を使うこと","方言を使う人が少なくなっていること"],"answer":2,"explain":"問題なのは、新しい言葉そのものではなく、相手や場面を考えずに言葉を使ってしまうこと. Option 2 is contradicted: young people try to use proper keigo at interviews."},{"q":"この文章で筆者が最も言いたいことは何か。","options":["言葉の変化を{嘆|なげ}くより、場面に合った言葉を選ぶ力を育てることが大切だ。","若者の言葉の乱れを防ぐために、大人が正しい言葉を教えるべきだ。","新しい言葉には工夫があるので、どんな場面でも積極的に使うべきだ。","方言と同じように、若者の言葉も大切に残していくべきだ。"],"answer":0,"explain":"The final paragraph: rather than lamenting change, develop the ability to choose words suited to the situation."}]}]},{"sec":"dokkai","no":14,"type":"info","instr":"右のページは、さくら市国際交流協会の「日本文化体験プログラム」の案内である。下の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"さくら市国際交流協会\n秋の日本文化体験プログラム　参加者募集\n\n① 書道体験\n　日時：10月7日（土）10:00〜12:00\n　会場：市民会館　2階和室\n　参加費：800円（道具代込み）　定員：15名\n\n② 和菓子作り\n　日時：10月14日（土）13:00〜15:30\n　会場：市民会館　調理室\n　参加費：1,500円（材料費込み）　定員：12名\n　※小学生以下の方は、{保護者|ほごしゃ}と一緒にお申し込みください（{保護者|ほごしゃ}の方も参加費が必要です）。\n\n③ 茶道体験\n　日時：10月22日（日）14:00〜16:00\n　会場：さくら公園内　茶室「{松風|まつかぜ}」\n　参加費：1,000円　定員：10名\n　※正座が難しい方には、いすを用意します。お申し込みの際にお知らせください。\n\n④ 着物で町歩き\n　日時：10月29日（日）9:30〜12:30\n　集合：さくら駅東口\n　参加費：3,000円（着物レンタル・着付け代込み）　定員：8名\n　※雨の場合は11月5日（日）に延期します。\n\n【お申し込み方法】\n・協会ホームページの申込フォーム、またはお電話でお申し込みください。\n・申込期間：9月15日（金）〜各プログラムの{実施日|じっしび}の1週間前まで\n・定員を超えた場合は{抽選|ちゅうせん}となります。結果は{実施日|じっしび}の5日前までにメールでお知らせします。\n・さくら市に在住・在勤・在学の方は、参加費が半額になります。お申し込みの際にお知らせください。\n\nお問い合わせ：さくら市国際交流協会　TEL 0123-45-6789","questions":[{"q":"となりの町に住み、さくら市の大学に通っている留学生のリンさんは、日曜日の午後のプログラムに参加したいと思っている。リンさんが払う参加費はいくらか。","options":["1,000円","750円","1,500円","500円"],"answer":3,"explain":"The only Sunday-afternoon program is ③ tea ceremony (1,000 yen). She studies in Sakura City, so she pays half: 500 yen."},{"q":"マリアさんは、8歳の娘と一緒に和菓子作りに参加したいと考えている。マリアさんはどうしなければならないか。","options":["10月14日の当日までに、電話で申し込む。","10月7日までに、親子2人分を申し込む。","娘1人分だけを申し込み、当日は一緒に会場へ行く。","9月15日までに、ホームページから申し込む。"],"answer":1,"explain":"Deadline is one week before 10/14, i.e. 10/7; children of primary-school age must apply with a guardian, and the guardian also pays, so she applies for two."}]}]}]},"l":{"mondai":[{"no":1,"type":"task","instr":"問題１では、まず質問を聞いてください。それから話を聞いて、問題用紙の１から４の中から、最もよいものを一つ選んでください。","items":[{"intro":"旅行会社で、男の人と店の人が話しています。男の人はこのあとまず何をしなければなりませんか。","question":"男の人はこのあとまず何をしなければなりませんか。","lines":[{"sp":"F","ja":"お申し込みありがとうございます。こちらの台湾のツアーですね。","en":"Thank you for booking. This is the Taiwan tour, right?"},{"sp":"M","ja":"はい。支払いは今日しちゃったほうがいいですか。","en":"Yes. Should I pay today?"},{"sp":"F","ja":"お支払いは出発の二週間前までで{大丈夫|だいじょうぶ}です。それより、パスポートの有効期限はご確認されましたか。入国のときに三か月以上残っていないといけないんです。","en":"Payment is fine up to two weeks before departure. More importantly, have you checked your passport's expiry date? It must have at least three months left when you enter the country."},{"sp":"M","ja":"あ、たしか来年の春までだったと思うんですけど…。","en":"Oh, I think it's valid until next spring..."},{"sp":"F","ja":"でしたら、ぎりぎりかもしれませんね。足りなければ作り直していただくことになりますし、そうなると申込書に書く番号も変わりますので、先にそちらをはっきりさせていただけますか。","en":"Then it might be cutting it close. If it's not enough you'll need a new one, and then the number on the form changes, so could you make that clear first?"},{"sp":"M","ja":"わかりました。じゃあ、家に帰ってすぐ見てみます。申込書はそのあとでいいですね。","en":"Got it. I'll check as soon as I get home. The form can wait until after that, right?"},{"sp":"F","ja":"はい、パスポートの番号が決まってからご記入ください。","en":"Yes, please fill it in once the passport number is settled."}],"options":["旅行の代金を払う","パスポートの期限を確かめる","申込書に記入する","パスポートを作り直す"],"answer":1,"explain":"Payment can wait; he must first check whether his passport has enough validity. Renewing is only needed if it's too short, and the form comes after."},{"intro":"町の祭りのボランティアの説明会で、係の女の人と男の人が話しています。男の人は祭りの日に何を持っていかなければなりませんか。","question":"男の人は祭りの日に何を持っていかなければなりませんか。","lines":[{"sp":"F","ja":"当日は朝八時に公民館に集合です。法被はこちらで用意しますので、持ってこなくて{大丈夫|だいじょうぶ}ですよ。","en":"On the day, gather at the community hall at 8 a.m. We'll provide the happi coats, so you don't need to bring one."},{"sp":"M","ja":"お昼ご飯はどうなりますか。","en":"What about lunch?"},{"sp":"F","ja":"お{弁当|べんとう}が出ます。ただ、飲み物は各自でお願いします。一日中外で動きますから、多めに持ってきてくださいね。","en":"A boxed lunch is provided. But please bring your own drinks. You'll be moving around outside all day, so bring plenty."},{"sp":"M","ja":"わかりました。帽子もあったほうがいいですか。","en":"OK. Should I bring a hat as well?"},{"sp":"F","ja":"帽子は、お配りするタオルを頭に巻いていただくので、なくていいです。あ、それから、名札を先週お渡ししましたよね。あれは必ずつけてきてください。","en":"No hat needed; you'll wrap the towel we hand out around your head. Oh, and we gave you a name tag last week, didn't we? Be sure to wear it."},{"sp":"M","ja":"あれ、名札は受付でもらえるんじゃなかったんですか。","en":"Huh, I thought we'd get name tags at reception."},{"sp":"F","ja":"去年まではそうだったんですけど、今年は前もってお配りしたんです。","en":"That was how it worked until last year, but this year we handed them out in advance."},{"sp":"M","ja":"そうですか。じゃあ、忘れないようにします。","en":"I see. I'll make sure not to forget it."}],"options":["帽子と名札","お{弁当|べんとう}と飲み物","法被と飲み物","飲み物と名札"],"answer":3,"explain":"Happi coat, lunch and towel are provided; no hat needed. He must bring drinks and the name tag he already received."},{"intro":"大学で、女の学生と先生が話しています。女の学生はこのあとまず何をしますか。","question":"女の学生はこのあとまず何をしますか。","lines":[{"sp":"F","ja":"先生、方言のレポートのことでご相談が…。地元のお年寄りにインタビューしたいんですが、質問のリストはもう作ってあります。","en":"Professor, I'd like to talk about my dialect report. I want to interview elderly local people, and I've already made the question list."},{"sp":"M","ja":"そう。録音するつもり？","en":"I see. Are you going to record it?"},{"sp":"F","ja":"はい、そのつもりです。","en":"Yes, I plan to."},{"sp":"M","ja":"それなら、相手の方に録音の許可をもらう書類が必要だよ。大学の決まりでね。書式は研究室のホームページにあるから。","en":"Then you need a form to get permission from the interviewees to record. It's a university rule. The template is on the lab's website."},{"sp":"F","ja":"わかりました。じゃあ、今日中に印刷して…。","en":"OK. Then I'll print it today and..."},{"sp":"M","ja":"あ、ただ、その前に研究計画書を出してもらわないと、私がその書類にサインできないんだ。計画書はもう出した？","en":"Oh, but I can't sign that form until you've submitted a research plan. Have you submitted it yet?"},{"sp":"F","ja":"いえ、まだです。","en":"No, not yet."},{"sp":"M","ja":"じゃ、まずそっちだね。質問のリストも一緒につけて出してくれる？","en":"Then that comes first. Can you attach the question list too when you submit it?"},{"sp":"F","ja":"はい、わかりました。","en":"Yes, understood."}],"options":["質問のリストを作る","録音の許可の書類を印刷する","研究計画書を出す","お年寄りにインタビューする"],"answer":2,"explain":"The question list is done; the permission form can't be signed until the research plan is submitted, so the plan comes first."},{"intro":"地域の情報誌の編集部で、女の人と男の人が話しています。男の人はこのあとまず何をしなければなりませんか。","question":"男の人はこのあとまず何をしなければなりませんか。","lines":[{"sp":"M","ja":"編集長、来月号の{商店街|しょうてんがい}特集の{原稿|げんこう}、できました。","en":"Chief, the draft for next month's shopping-street feature is done."},{"sp":"F","ja":"ありがとう。読ませてもらったけど、内容はいいと思う。ただ、パン屋さんの写真がちょっと暗いのよね。","en":"Thanks. I've read it and the content is good. But the bakery photo is a bit dark."},{"sp":"M","ja":"あ、{撮|と}り直してきましょうか。","en":"Shall I go and retake it?"},{"sp":"F","ja":"うーん、実はね、あのパン屋さん、来月から営業時間が変わるらしいの。記事に書いてある時間で合ってるか、まず確認してくれない？写真は私が前に{撮|と}ったのが使えるかもしれないから、あとで探してみる。","en":"Well, actually, I hear the bakery's opening hours change from next month. Could you first check whether the hours in the article are right? I might be able to use a photo I took before, so I'll look for it later."},{"sp":"M","ja":"わかりました。電話で聞いてみます。変わっていたら{原稿|げんこう}を直して、もう一度お送りします。","en":"Understood. I'll phone them. If it's changed, I'll fix the draft and send it again."},{"sp":"F","ja":"お願い。","en":"Please."}],"options":["パン屋に営業時間を確認する","パン屋の写真を{撮|と}り直す","編集長の写真を探す","{原稿|げんこう}を編集長に送る"],"answer":0,"explain":"The chief will look for her own photo; he must first phone the bakery to confirm the opening hours, then fix and resend the draft."},{"intro":"旅館のフロントで、女の客と旅館の人が話しています。女の人はこのあとまず何をしますか。","question":"女の人はこのあとまず何をしますか。","lines":[{"sp":"F","ja":"すみません、明日の朝、近くの朝市に行ってみたいんですけど。","en":"Excuse me, I'd like to go to the nearby morning market tomorrow."},{"sp":"M","ja":"ああ、朝市は六時から八時ごろまでですね。ここから歩いて十五分ほどです。","en":"Ah, the market runs from six to about eight. It's about fifteen minutes' walk from here."},{"sp":"F","ja":"朝食は七時からでしたよね。朝市から戻ってからでも間に合いますか。","en":"Breakfast starts at seven, right? Will I still make it after coming back from the market?"},{"sp":"M","ja":"はい、九時半まで{大丈夫|だいじょうぶ}です。それから、朝市は現金しか使えないお店がほとんどなんですよ。","en":"Yes, it's fine until 9:30. Also, most stalls at the market only take cash."},{"sp":"F","ja":"あ、現金、あまり持ってないんです。この辺にATMはありますか。","en":"Oh, I don't have much cash. Is there an ATM around here?"},{"sp":"M","ja":"駅前のコンビニにありますが、朝市とは反対の方向なんです。今のうちに行っておかれたほうがいいと思いますよ。{玄関|げんかん}は夜十時まで開いておりますので。","en":"There's one at the convenience store by the station, but it's in the opposite direction from the market. I'd recommend going now. The entrance is open until 10 p.m."},{"sp":"F","ja":"そうですね。じゃあ、今から行ってきます。","en":"Good idea. I'll go now, then."}],"options":["朝市に行く","朝ご飯を食べる","{玄関|げんかん}が閉まる時間を確かめる","コンビニでお金を下ろす"],"answer":3,"explain":"The market only takes cash and the ATM is the other way, so she goes to the convenience store now to withdraw money."}]},{"no":2,"type":"point","instr":"問題２では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、問題用紙の１から４の中から、最もよいものを一つ選んでください。","items":[{"intro":"ラジオで、女の人がある町の映画館について話しています。女の人は、この映画館が続いてきた一番の理由は何だと言っていますか。","question":"この映画館が続いてきた一番の理由は何だと言っていますか。","lines":[{"sp":"F","ja":"今日ご紹介するのは、今年で七十年を迎えた、港町の小さな映画館です。座席はわずか五十席。最新の設備があるわけでも、話題の新作をいち早く上映するわけでもありません。一時は閉館も考えたそうです。それでも続けてこられたのは、館主の方によると、上映のあとに開く小さな集まりのおかげなんだそうです。映画を見た人たちが、お茶を飲みながら感想を話し合う。そこで知り合った人たちが、次の上映会に友達を連れてくる。料金の安さを理由に{挙|あ}げる常連さんもいますが、館主は「人が集まる場所になれたことが何より大きい」と話していました。","en":"Today we introduce a small cinema in a port town that turns seventy this year. Only fifty seats. It neither has the latest equipment nor shows hit new releases early. At one point they even considered closing. According to the owner, they kept going thanks to small gatherings held after screenings: viewers chat over tea, and people who meet there bring friends next time. Some regulars cite the low prices, but the owner said becoming a place where people gather mattered more than anything."}],"options":["料金が安いから","見た人{同士|どうし}が交流できる場があるから","最新の設備があるから","新作をすぐに上映するから"],"answer":1,"explain":"The owner credits the after-screening gatherings. Low price is only what some regulars say; equipment and new releases are explicitly denied."},{"intro":"男の人と女の人が、旅行について話しています。女の人はどうして旅行で写真をあまり{撮|と}らなかったのですか。","question":"女の人はどうして旅行で写真をあまり{撮|と}らなかったのですか。","lines":[{"sp":"M","ja":"旅行どうだった？写真見せてよ。","en":"How was the trip? Show me your photos."},{"sp":"F","ja":"それがね、今回はほとんど{撮|と}らなかったの。","en":"Well, this time I hardly took any."},{"sp":"M","ja":"え、カメラ{壊|こわ}れたの？","en":"What, did your camera break?"},{"sp":"F","ja":"ううん。前は何でも{撮|と}ってたんだけど、家に帰って見返すと、写真はたくさんあるのに、そこで何を感じたか全然覚えてないことに気がついて。","en":"No. I used to photograph everything, but when I looked back at home I realised that despite all the photos I didn't remember at all what I'd felt there."},{"sp":"M","ja":"ああ、それはあるかも。","en":"Ah, that can happen."},{"sp":"F","ja":"{撮|と}ることに夢中で、景色をちゃんと見てなかったんだよね。だから今回は、自分の目でゆっくり見ることにしたの。","en":"I was so absorbed in shooting that I wasn't really looking at the scenery. So this time I decided to take it in slowly with my own eyes."},{"sp":"M","ja":"てっきり、SNSに{載|の}せるのが面倒になったのかと思った。","en":"I was sure you'd got tired of posting on social media."},{"sp":"F","ja":"それはもともとあんまりやってないし。","en":"I never really did that much anyway."}],"options":["カメラが{壊|こわ}れたから","SNSに{載|の}せるのが面倒になったから","景色を自分の目でしっかり見たいと思ったから","写真が多すぎて整理できないから"],"answer":2,"explain":"She realised she had not really been looking, so she chose to see the scenery with her own eyes. The camera and SNS guesses are both denied."},{"intro":"日本語学校で、先生と男の留学生が話しています。男の留学生はスピーチ大会で何について話すことにしましたか。","question":"男の留学生はスピーチ大会で何について話すことにしましたか。","lines":[{"sp":"M","ja":"先生、スピーチ大会のテーマ、やっと決まりました。","en":"Teacher, I've finally decided on my speech contest topic."},{"sp":"F","ja":"よかった。前は日本のアニメの話にするって言ってたよね。","en":"Good. Before, you said you'd talk about Japanese anime."},{"sp":"M","ja":"はい。でも、アニメの話をする人はほかにも多いみたいで…。それで、アルバイト先の居酒屋で覚えた言葉のことを話そうかとも考えたんですけど。","en":"Yes. But it seems lots of others are doing anime... So I also thought about talking about words I learned at the izakaya where I work part-time."},{"sp":"F","ja":"うん、面白そう。","en":"That sounds interesting."},{"sp":"M","ja":"ただ、店長に聞いたら、お店の名前を出すのはちょっと…って。それで結局、国の料理を近所のおばあさんに教えたときの話にしました。言葉がうまく通じなくても、一緒に作っているうちに仲良くなれたので。","en":"But when I asked the manager, he wasn't keen on the shop being named. So in the end I chose the time I taught my country's cooking to an elderly neighbour. Even though we couldn't communicate well, we became friends while cooking together."},{"sp":"F","ja":"いいテーマだね。","en":"That's a good topic."}],"options":["近所の人と一緒に料理をした経験","日本のアニメ","アルバイト先で覚えた言葉","国の料理の作り方"],"answer":0,"explain":"Anime was dropped (too common), the izakaya topic was vetoed by the manager; he chose his experience of cooking with an elderly neighbour, not the recipe itself."},{"intro":"テレビで、アナウンサーが温泉町の男の人にインタビューしています。男の人は、若い観光客が増えた一番のきっかけは何だと言っていますか。","question":"男の人は、若い観光客が増えた一番のきっかけは何だと言っていますか。","lines":[{"sp":"F","ja":"こちらの温泉町、ここ数年で若い観光客がずいぶん増えたそうですね。","en":"I hear this hot-spring town has seen many more young tourists in recent years."},{"sp":"M","ja":"ええ、おかげさまで。よく、駅が新しくなったからだろうと言われるんですが、駅ができる前から少しずつ増えてはいたんです。","en":"Yes, thankfully. People often say it's because the station was rebuilt, but numbers were already rising before the new station."},{"sp":"F","ja":"そうなんですか。","en":"Really?"},{"sp":"M","ja":"はい。大きかったのは、町の空き家を使った宿ですね。古い民家を若い人たちが直して、{素泊|すど}まりの安い宿にしたんです。それが雑誌に取り上げられて、一気に知られるようになりました。","en":"Yes. The big thing was lodgings in the town's empty houses. Young people renovated old homes into cheap room-only inns. Magazines covered them and suddenly the town became known."},{"sp":"F","ja":"温泉そのものの人気ではなく？","en":"Not the popularity of the hot springs themselves?"},{"sp":"M","ja":"もちろん温泉は昔からの{自慢|じまん}ですけど、温泉だけでは若い人はなかなか来てくれませんでしたから。","en":"Of course the springs have always been our pride, but the springs alone never really brought in young people."}],"options":["駅が新しくなったこと","空き家を宿にしたこと","温泉が人気になったこと","町が雑誌に広告を出したこと"],"answer":1,"explain":"He rejects the station theory and says the inns made from empty houses were the big factor. The magazine covered them; the town did not advertise."},{"intro":"男の人と女の人が、新しくなった図書館について話しています。女の人は図書館の何がいいと言っていますか。","question":"女の人は図書館の何がいいと言っていますか。","lines":[{"sp":"M","ja":"駅前の図書館、新しくなってから行った？","en":"Have you been to the station library since it reopened?"},{"sp":"F","ja":"うん、先週行ったよ。カフェが入ってて便利だって聞いてたけど、私はあんまり使わないかな。本の数も前とそんなに変わらないし。","en":"Yes, last week. I'd heard the new café makes it convenient, but I probably won't use it much. And the number of books isn't that different from before."},{"sp":"M","ja":"そうなんだ。","en":"I see."},{"sp":"F","ja":"でもね、地元の古い写真とか昔の地図を見られるコーナーができてて、それがすごくよかった。うちの近所が昔は田んぼだったなんて知らなかったよ。","en":"But there's a new corner where you can see old local photos and maps, and that was great. I never knew my neighbourhood used to be rice fields."},{"sp":"M","ja":"へえ。夜も遅くまで開いてるんでしょ？","en":"Wow. It's open late at night too, isn't it?"},{"sp":"F","ja":"九時までね。でも私は昼間しか行かないから。","en":"Until nine. But I only go in the daytime."}],"options":["カフェがあること","本の数が増えたこと","夜遅くまで開いていること","町の昔の様子がわかる資料があること"],"answer":3,"explain":"She praises the corner of old local photos and maps. Café and late hours don't matter to her; book numbers haven't changed."},{"intro":"会社で、女の人と男の人が茶道教室について話しています。男の人が茶道教室をやめた理由は何ですか。","question":"男の人が茶道教室をやめた理由は何ですか。","lines":[{"sp":"F","ja":"田中さん、茶道の教室、まだ通ってるんですか。","en":"Mr. Tanaka, are you still going to your tea ceremony class?"},{"sp":"M","ja":"いや、先月やめたんだ。","en":"No, I quit last month."},{"sp":"F","ja":"え、正座がつらいって言ってましたもんね。","en":"Oh, you did say sitting seiza was hard."},{"sp":"M","ja":"それはもう慣れたんだけどね。先生も優しかったし、作法を覚えるのも楽しかったんだよ。ただ、教室が土曜の朝から日曜の夕方に変わっちゃって。日曜の夕方は子どものサッカーの送り迎えがあるから、どうしても行けなくなったんだ。","en":"I'd got used to that. The teacher was kind and learning the etiquette was fun. But the class moved from Saturday morning to Sunday evening, and on Sunday evenings I drive my kid to and from football, so I just couldn't go any more."},{"sp":"F","ja":"そうだったんですか。残念ですね。","en":"I see. That's a shame."},{"sp":"M","ja":"時間の合う教室が見つかったら、また始めたいと思ってるよ。","en":"If I find a class at a time that suits me, I'd like to start again."}],"options":["正座がつらかったから","作法を覚えるのが大変だったから","教室の日時が変わったから","先生が{厳|きび}しかったから"],"answer":2,"explain":"He'd got used to seiza and enjoyed it; the class moved to Sunday evening, when he has to ferry his child."}]},{"no":3,"type":"gist","instr":"問題３では、問題用紙に何もいんさつされていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、１から４の中から、最もよいものを一つ選んでください。","items":[{"intro":"ラジオで、男の人が話しています。","question":"男の人は何について話していますか。","lines":[{"sp":"M","ja":"日本の駅では、「白線の内側までお下がりください」「{駆|か}け込み乗車はおやめください」といったアナウンスが一日中流れています。海外から来た人の中には、これを「うるさい」と感じる人も少なくないようです。実は、鉄道会社の中にも、アナウンスを減らそうという動きがあります。何度も同じことを{繰|く}り返すと、かえって{誰|だれ}も聞かなくなり、本当に大切な情報が伝わらなくなるからです。ある駅では、アナウンスを半分に減らした代わりに表示を分かりやすくしたところ、利用者からの苦情はほとんどなかったそうです。情報は、多ければいいというものではないのかもしれません。","en":"Japanese stations broadcast announcements all day like 'Please stand behind the white line' and 'Please don't rush onto the train'. Quite a few visitors from abroad find this noisy. In fact some railway companies are moving to cut announcements, because repeating the same thing makes people stop listening and the truly important information doesn't get through. One station halved its announcements and made its signs clearer instead, and there were almost no complaints. Perhaps more information isn't always better."}],"options":["外国人観光客が駅で困っていること","駅のアナウンスを減らす取り組み","駅の表示が分かりにくいこと","鉄道会社への苦情が増えていること"],"answer":1,"explain":"The talk is about efforts to reduce station announcements and why. Signs were improved, and complaints were few."},{"intro":"大学の授業で、先生が話しています。","question":"先生の話のテーマは何ですか。","lines":[{"sp":"F","ja":"みなさんは毎日、メッセージに絵文字を使っていると思います。絵文字は日本の{携帯電話|けいたいでんわ}から生まれ、今では世界中で使われています。言葉が違っても意味が通じる、便利な道具だと考えられがちですね。ところが、調査をしてみると、同じ絵文字でも、国や世代によって受け取り方がかなり違うことが分かってきました。たとえば、ある笑顔の絵文字を、若い人は「あきれている」という意味で使うことがありますが、年配の人は{素直|すなお}に「うれしい」と受け取ります。つまり絵文字も、言葉と同じように、使う人たちの文化の中で意味が決まっていくものなのです。","en":"You probably all use emoji in messages every day. Emoji were born on Japanese mobile phones and are now used worldwide. People tend to think of them as a handy tool understood regardless of language. But research shows the same emoji is read quite differently depending on country and generation. For example, young people may use a certain smiley to mean exasperation, while older people take it simply as happy. In other words, like words, emoji get their meaning within the culture of the people who use them."}],"options":["絵文字が日本で生まれた歴史","絵文字の正しい使い方","絵文字の意味が使う人によって異なること","若い人が絵文字を使わなくなった理由"],"answer":2,"explain":"The main point is that emoji meanings differ by country and generation, i.e. by the users' culture."},{"intro":"テレビで、レポーターが{商店街|しょうてんがい}から話しています。","question":"レポーターは主に何について伝えていますか。","lines":[{"sp":"F","ja":"こちらは駅から歩いて五分ほどの{商店街|しょうてんがい}です。シャッターが閉まったままのお店が目立ちますが、この一角だけはにぎやかですね。実はここ、元は靴屋さんだった空き{店舗|てんぽ}なんです。中にはたくさんの{本棚|ほんだな}が並んでいて、その{棚|たな}の一つ一つを地域の人が借りて、自分のおすすめの本を置いています。訪れた人は、その本を買ったり、{棚|たな}の持ち主が書いたメッセージを読んだりできます。{棚|たな}を借りているのは会社員や学生、定年を迎えた方などさまざまで、ここで知り合った人{同士|どうし}が読書会を開くこともあるそうです。本をきっかけに、{商店街|しょうてんがい}に人の流れが戻りつつあります。","en":"This shopping street is about five minutes' walk from the station. Many shops have their shutters down, but this corner alone is lively. It's actually an empty shop that used to be a shoe store. Inside are many bookshelves, each rented by a local who puts out books they recommend. Visitors can buy the books or read messages from the shelf owners. Renters range from office workers and students to retirees, and people who meet here sometimes hold reading groups. Thanks to books, people are starting to come back to the street."}],"options":["空き{店舗|てんぽ}を使った、本を通じた交流の場","{商店街|しょうてんがい}に新しい本屋ができたこと","地域の人が開いている読書会の内容","{商店街|しょうてんがい}に空き{店舗|てんぽ}が増えている原因"],"answer":0,"explain":"The report is about a vacant shop turned into shared bookshelves that connect local people. It is not an ordinary new bookstore, and the reading groups are a side detail."},{"intro":"講演会で、{翻訳家|ほんやくか}の男の人が話しています。","question":"男の人は、{翻訳|ほんやく}で何が一番難しいと言っていますか。","lines":[{"sp":"M","ja":"私は長年、日本の小説を外国語に{訳|やく}す仕事をしてきました。よく「一番難しいのは何ですか」と聞かれます。皆さんは、難しい言葉や古い表現だと思われるかもしれません。でも、そういうものは辞書や資料で調べれば、たいてい何とかなります。本当に苦労するのは、書かれていないことなんです。日本語の文章では、主語が省略されたり、登場人物の気持ちがはっきり書かれなかったりすることがよくあります。日本の読者はそれを自然に読み取りますが、{訳|やく}すときには、{誰|だれ}が言ったのか、どう感じているのかを、ある程度はっきりさせなければなりません。そこで{訳者|やくしゃ}が読み間違えると、作品の印象がまったく変わってしまうのです。","en":"For many years I have translated Japanese novels into other languages. People often ask what is hardest. You may think it's difficult words or old expressions, but those can usually be handled with dictionaries and research. What I really struggle with is what isn't written. In Japanese, subjects are often omitted and characters' feelings left unstated. Japanese readers infer them naturally, but a translation has to make clear, to some degree, who said what and how they feel. If the translator misreads that, the whole impression of the work changes."}],"options":["難しい言葉や古い表現を{訳|やく}すこと","辞書や資料を集めること","外国の読者に人気が出る作品を選ぶこと","書かれていない意味を読み取って{訳|やく}すこと"],"answer":3,"explain":"Hard words can be looked up; the real difficulty is interpreting what the text leaves unsaid (omitted subjects, unstated feelings)."},{"intro":"旅館の人が電話で留守番電話にメッセージを残しています。","question":"旅館の人が一番伝えたいことは何ですか。","lines":[{"sp":"F","ja":"もしもし、山田様の{携帯電話|けいたいでんわ}でしょうか。こちら、今週末にご予約いただいております旅館「みどり{荘|そう}」でございます。実は、ご宿泊の日に、{露天風呂|ろてんぶろ}が設備の点検のため使えなくなってしまいました。大変申し{訳|わけ}ございません。大浴場は通常通りご利用いただけます。お{詫|わ}びとしまして、ご夕食に一品追加させていただきたいと考えております。もしこの内容でご宿泊が難しいようでしたら、キャンセル料はいただきませんので、お手数ですが、お電話をいただけますでしょうか。よろしくお願いいたします。","en":"Hello, is this Mr./Ms. Yamada's mobile? This is Midori-so, the inn you've booked for this weekend. Unfortunately, on the day of your stay the outdoor bath will be unavailable due to equipment inspection. We sincerely apologise. The main bath is available as usual. As an apology we would like to add one dish to your dinner. If staying under these conditions is difficult, we won't charge a cancellation fee, so could you please call us? Thank you."}],"options":["予約の日にちを変えてほしいこと","{露天風呂|ろてんぶろ}が使えないことと、その対応","夕食の内容が変わること","キャンセル料がかかること"],"answer":1,"explain":"The main message: the outdoor bath can't be used, plus what the inn offers (extra dish, free cancellation). No cancellation fee is charged."}]},{"no":4,"type":"response","instr":"問題４では、問題用紙に何もいんさつされていません。まず文を聞いてください。それから、それに対する返事を聞いて、１から３の中から、最もよいものを一つ選んでください。","items":[{"intro":"","question":"","lines":[{"sp":"F","ja":"田中さん、京都のお土産、わざわざありがとうございます。","en":"Mr. Tanaka, thank you for going to the trouble of bringing a souvenir from Kyoto."}],"options":["いえ、ほんの気持ちですから。","はい、ぜひ買ってきてください。","京都は行ったことがないんです。"],"answer":0,"explain":"A modest reply to thanks for a gift: it's just a small token."},{"intro":"","question":"","lines":[{"sp":"M","ja":"今度の連休は、実家に帰るどころじゃないんだよ。","en":"This coming long weekend, going home to my parents' is out of the question."}],"options":["じゃあ、ゆっくりしてきてね。","そんなに忙しいの？","実家はどこにあるの？"],"answer":1,"explain":"〜どころじゃない = no way I can (I'm too busy). The natural reply asks if he's that busy."},{"intro":"","question":"","lines":[{"sp":"F","ja":"この店のラーメン、並んでまで食べるほどのものじゃないと思うけど。","en":"I don't think this shop's ramen is worth queuing for."}],"options":["じゃあ、もっと並ぼうか。","うん、並んだかいがあったね。","そう？私はおいしいと思うけどな。"],"answer":2,"explain":"She says it's not worth the wait; replying that you find it tasty fits. The others contradict her."},{"intro":"","question":"","lines":[{"sp":"M","ja":"部長、来週の出張の件で、ちょっとよろしいでしょうか。","en":"Manager, may I have a moment about next week's business trip?"}],"options":["ああ、何？","うん、よろしく伝えておいて。","出張、楽しんできてね。"],"answer":0,"explain":"ちょっとよろしいでしょうか asks for a moment of time; 'Sure, what is it?' is the right answer."},{"intro":"","question":"","lines":[{"sp":"F","ja":"雨が降らないうちに、洗濯物を取り込んでおいたら？","en":"Why not bring in the laundry before it starts raining?"}],"options":["本当だ、もう降ってきたね。","そうだね、今のうちにやっとく。","じゃあ、雨がやんでから干すよ。"],"answer":1,"explain":"〜ないうちに = before (it rains). Agreeing to do it now fits; it hasn't started raining yet."},{"intro":"","question":"","lines":[{"sp":"M","ja":"あの映画、原作を読んでから見ればよかったなあ。","en":"I wish I'd read the original novel before seeing that film."}],"options":["原作を読んでから見たんだね。","じゃあ、早く見に行けばよかったのに。","そうだね、原作には細かい話も書いてあるからね。"],"answer":2,"explain":"〜ばよかった = regret: he didn't read it first. Agreeing that the book has more detail fits."},{"intro":"","question":"","lines":[{"sp":"F","ja":"{佐藤|さとう}さんの発表、時間をかけて準備しただけのことはあったね。","en":"Sato's presentation really showed all the time she put into preparing."}],"options":["うん、本当に分かりやすかった。","うん、もっと準備すればよかったのにね。","時間が足りなかったみたいだね。"],"answer":0,"explain":"〜だけのことはある = it was worth it, as expected. Praising the presentation fits."},{"intro":"","question":"","lines":[{"sp":"M","ja":"すみません、この席、どなたかいらっしゃいますか。","en":"Excuse me, is anyone sitting here?"}],"options":["はい、いらっしゃいませ。","あちらにいらっしゃいます。","いえ、どうぞ。"],"answer":2,"explain":"He's asking if the seat is taken; 'No, go ahead' is the answer."},{"intro":"","question":"","lines":[{"sp":"F","ja":"山本さんって、日本語が上手すぎて留学生とは思えないよね。","en":"Yamamoto's Japanese is so good you'd never think he's an international student."}],"options":["うん、まだ来たばかりだもんね。","そうそう、話し方も自然だよね。","留学生だったら、もっと勉強しないと。"],"answer":1,"explain":"Agreeing that his speech is natural fits the compliment."},{"intro":"","question":"","lines":[{"sp":"M","ja":"例の{企画|きかく}、結局見送られることになったよ。","en":"That project we talked about — in the end they've decided to shelve it."}],"options":["え、あんなに準備したのに？","じゃあ、駅まで見送りに行こう。","よかった、ついに始まるんだね。"],"answer":0,"explain":"見送られる here = postponed/dropped. Surprise after all the preparation fits; option 2 takes 見送る literally (see someone off)."},{"intro":"","question":"","lines":[{"sp":"F","ja":"{先輩|せんぱい}、明日の観光ガイド、私が代わりに行きましょうか。","en":"Senpai, shall I do tomorrow's tour guiding in your place?"}],"options":["うん、代わりに行ってもらったよ。","じゃあ、明日私が行ってくるね。","本当？助かるよ。"],"answer":2,"explain":"She offers to go instead; thanking her ('That'd be a big help') fits."},{"intro":"","question":"","lines":[{"sp":"M","ja":"今朝の電車、混んでるなんてもんじゃなかったよ。","en":"This morning's train — 'crowded' doesn't even begin to describe it."}],"options":["へえ、空いててよかったね。","そんなにひどかったの？","じゃあ、座れたんだね。"],"answer":1,"explain":"〜なんてもんじゃない = far more than X. It was extremely crowded, so 'Was it that bad?' fits."}]},{"no":5,"type":"integrated","instr":"問題５では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。１番、２番は、問題用紙に何もいんさつされていません。まず話を聞いてください。それから、質問とせんたくしを聞いて、１から４の中から、最もよいものを一つ選んでください。３番は、まず話を聞いてください。それから、二つの質問を聞いて、それぞれ問題用紙の１から４の中から、最もよいものを一つ選んでください。","items":[{"intro":"旅行会社で、男の人と店の人が話しています。","question":"男の人はどのツアーを選びましたか。","lines":[{"sp":"M","ja":"両親の結婚四十周年のお祝いに、国内旅行をプレゼントしたいんですが、おすすめはありますか。","en":"I'd like to give my parents a domestic trip for their 40th wedding anniversary. Any recommendations?"},{"sp":"F","ja":"はい。こちらの四つが人気です。まず一つ目は、北海道の湖を{巡|めぐ}るツアーです。景色はすばらしいんですが、一日にかなり歩きます。","en":"Yes, these four are popular. The first is a tour of Hokkaido's lakes. The scenery is wonderful, but you walk quite a lot each day."},{"sp":"M","ja":"父は最近{膝|ひざ}を悪くしていて、長く歩くのはちょっと…。","en":"My father's knee has been bad lately, so long walks are a bit..."},{"sp":"F","ja":"でしたら、二つ目の京都のお寺を{巡|めぐ}るツアーはいかがでしょう。タクシーで回りますので、歩く{距離|きょり}は短いです。","en":"Then how about the second, a Kyoto temple tour? You go round by taxi, so there's little walking."},{"sp":"M","ja":"いいですね。ただ、京都は去年二人で行ったばかりなんですよ。","en":"Sounds good. But they only went to Kyoto together last year."},{"sp":"F","ja":"そうですか。三つ目は、九州の温泉を観光列車で回るツアーです。列車の中で地元の料理も楽しめます。","en":"I see. The third goes round Kyushu's hot springs by sightseeing train. You can enjoy local food on board too."},{"sp":"M","ja":"列車なら座っていられますね。母は温泉が大好きなんです。","en":"On a train they can stay seated. My mother loves hot springs."},{"sp":"F","ja":"四つ目は、{沖縄|おきなわ}の{離島|りとう}でのんびり過ごすツアーです。ただ、島へは小さな船で渡ります。","en":"The fourth is a relaxing stay on a remote Okinawan island. But you cross to the island on a small boat."},{"sp":"M","ja":"母は船に弱いので、それはやめておきます。じゃあ、母の好きなところにします。","en":"My mother gets seasick, so not that one. I'll go with the place my mother likes, then."}],"options":["北海道の湖を{巡|めぐ}るツアー","京都の寺を{巡|めぐ}るツアー","九州の温泉を列車で回るツアー","{沖縄|おきなわ}の{離島|りとう}で過ごすツアー"],"answer":2,"explain":"Hokkaido: too much walking for the father. Kyoto: they went last year. Okinawa: mother gets seasick. He picks the Kyushu hot-spring train tour his mother would love."},{"intro":"市の国際交流センターで、職員三人が来月のイベントについて話しています。","question":"イベントで何をすることにしましたか。","lines":[{"sp":"F","ja":"来月の交流イベント、そろそろ何をするか決めないと。案は三つ出てたよね。料理教室と、日本語のスピーチ発表会と、町歩きツアー。","en":"We need to decide on next month's exchange event. There were three ideas: a cooking class, a Japanese speech presentation, and a town walking tour."},{"sp":"M","ja":"料理教室は去年好評だったけど、調理室が工事で来月は使えないんだよね。","en":"The cooking class went down well last year, but the kitchen is under renovation and can't be used next month."},{"sp":"F","ja":"そうなんだ。じゃあ無理か。スピーチ発表会はどう？留学生の日本語の練習にもなるし。","en":"Oh, then that's out. How about the speech presentation? It's good Japanese practice for international students."},{"sp":"M","ja":"うーん、ただ、今回の目的は、外国人の住民と日本人の住民が知り合うことでしょう？発表会だと、聞く側は座っているだけになっちゃうから。","en":"Hmm, but this time the aim is for foreign and Japanese residents to get to know each other, right? At a presentation, the audience just sits there."},{"sp":"F","ja":"そうね。町歩きなら、歩きながら自然に話せるし、地元の人に案内役をお願いすれば交流にもなる。","en":"True. On a town walk people can chat naturally while walking, and if we ask locals to be guides, that's exchange too."},{"sp":"F","ja":"でも来月って寒くない？雨が降ったらどうするの？","en":"But won't it be cold next month? What if it rains?"},{"sp":"M","ja":"雨の場合は、{商店街|しょうてんがい}のアーケードの中だけを回るコースにすればいいよ。","en":"If it rains, we can use a route that stays inside the shopping arcade."},{"sp":"F","ja":"それなら安心ね。じゃあ、それで進めましょう。","en":"That's reassuring. Let's go with that, then."}],"options":["料理教室","スピーチ発表会","{商店街|しょうてんがい}での買い物","町歩きツアー"],"answer":3,"explain":"Cooking class: kitchen unavailable. Speech event: audience just sits, poor for mixing. They choose the town walk, with an arcade route if it rains (the arcade is a backup route, not a shopping event)."},{"intro":"ラジオで、アナウンサーが今週末の文化イベントについて話しています。それを聞いて、男の人と女の人が話しています。","lines":[{"sp":"N","ja":"今週末、市内では四つの文化イベントが開かれます。まず、市民会館では「世界の絵本展」。三十か国の絵本を、実際に手に取って読むことができます。次に、{城跡|しろあと}公園では「{伝統|でんとう}工芸フェア」。職人の方の指導で、{漆塗|うるしぬ}りの{箸|はし}づくりが体験できます。ただし、事前の予約が必要です。三つ目は、駅前広場の「ご当地グルメ市」。県内各地の名物が集まります。最後に、市立図書館では「方言落語会」。地元の言葉で演じられる落語を楽しめます。","en":"This weekend four cultural events are held in the city. First, at the Civic Hall, 'Picture Books of the World', where you can pick up and read picture books from thirty countries. Next, at Castle Ruins Park, the 'Traditional Crafts Fair', where craftspeople teach you to make lacquered chopsticks; advance booking required. Third, the 'Local Gourmet Market' in the station square, with specialities from all over the prefecture. Finally, at the city library, 'Dialect Rakugo', rakugo performed in the local dialect."},{"sp":"M","ja":"週末、どれか行ってみない？","en":"Shall we go to one of them this weekend?"},{"sp":"F","ja":"いいね。私、何か自分で作ってみたいな。{箸|はし}づくり、面白そう。","en":"Sure. I'd like to make something myself. The chopstick-making sounds fun."},{"sp":"M","ja":"でも、予約がいるって言ってたよね。もういっぱいかもよ。","en":"But they said you need to book. It might be full already."},{"sp":"F","ja":"さっきホームページを見たら、まだ空きがあったよ。私はそれにする。一緒にどう？","en":"I checked the website a moment ago and there were still places. I'll go for that. Want to come?"},{"sp":"M","ja":"{僕|ぼく}は手先が不器用だからなあ…。食べるのは好きだけど、駅前は人がすごいだろうし。","en":"I'm all thumbs, though... I like eating, but the station square will be packed."},{"sp":"F","ja":"じゃあ、落語は？地元の言葉を勉強してるって言ってたじゃない。","en":"What about the rakugo, then? You said you were studying the local dialect."},{"sp":"M","ja":"そうそう。引っ越してきてから、近所の人の話がまだ半分くらいしか分からないんだ。聞き取りの練習になるかもしれないし、それにするよ。","en":"Right. Since moving here I still only understand about half of what the neighbours say. It could be good listening practice, so I'll go to that."}],"subq":[{"question":"質問１　女の人はどのイベントに行きますか。","options":["世界の絵本展","{伝統|でんとう}工芸フェア","ご当地グルメ市","方言落語会"],"answer":1,"explain":"She wants to make something herself and found spaces left for the chopstick-making at the crafts fair."},{"question":"質問２　男の人はどのイベントに行きますか。","options":["世界の絵本展","{伝統|でんとう}工芸フェア","ご当地グルメ市","方言落語会"],"answer":3,"explain":"He's clumsy (not crafts) and the food market will be crowded; he picks dialect rakugo as listening practice."}],"question":""}]}]}};